class ConfigThread(threading.Thread):
    def __init__(self, robot : Robot):
        super().__init__()

        self.is_running = True
        self.daemon = True
        self.speech_cache = {}

        self.callbacks_ = {
            CONFIG_API_ID_AUDIO_REQUEST             : self._audio_request,
            CONFIG_API_ID_ADD_EXIHIBITION           : self._add_exihibition,
            CONFIG_API_ID_QUERY_EXIHIBITION         : self._query_exihibition,
            CONFIG_API_ID_DELETE_EXIHIBITION        : self._delete_exihibition,
            CONFIG_API_ID_GET_KNOWLEDGE_TEMP        : self._get_knowledge_temp,
            CONFIG_API_ID_UPLOAD_KNOWLEDGE          : self._upload_knowledge,
            CONFIG_API_ID_GET_KNOWLEDGE             : self._get_knowledge,
            CONFIG_API_ID_DELETE_KNOWLEDGE          : self._delete_knowledge,
            CONFIG_API_ID_UPDATE_LLM_API            : self._update_llm_api,
            CONFIG_API_ID_GET_LLM_API               : self._get_llm_api,
            CONFIG_API_ID_AUTO_NAV_SWITCH_GET       : self._auto_nav_switch_get,
            CONFIG_API_ID_AUTO_NAV_SWITCH_UPDATE    : self._auto_nav_switch_update,
            CONFIG_API_ID_ROLE_SET                  : self._role_set,
            CONFIG_API_ID_ROLE_GET                  : self._role_get,
            CONFIG_API_ID_GESTURE_SET               : self._gesture_set,
            CONFIG_API_ID_GESTURE_GET               : self._gesture_get,
            CONFIG_API_ID_SPEECH                    : self._speech_request,
            CONFIG_API_ID_SPEECH2                   : self._speech_request2,
            CONFIG_API_ID_INTTERUPT                 : self._interrupt,
            CONFIG_API_ID_GETTUNELIST               : self._gettunelist,
            CONFIG_API_ID_SAVESELECTTUNE            : self._saveselecttune,
            CONFIG_API_ID_GETTUNERESULT             : self._gettuneresult,
        }

        self.robot = robot

        set_app_config_listener(reader_app, self._on_data_available)

    def _interrupt(self, config_req):
        self.robot.interrupt(config_req)

        return STATE_SUCCESS, 'interrupt success', None

    def _audio_request(self, config_req):
        if isinstance(config_req, dict) :
            config_req = config_req['content']

        self.robot.speech_msgs_.append(config_req)
        return STATE_SUCCESS, 'audio request success', None

    def _parse_speech(self, req) :
        uid = req['uid']
        speech = req['speech']
        state = req['state']

        if uid not in self.speech_cache :
            self.speech_cache[uid] = {
                req['idx'] : req
            }
        else :
            self.speech_cache[uid][req['idx']] = req

        req = None
        if state == 'finish' :
            t1 = time.perf_counter()
            speech_chunks = self.speech_cache[uid]
            # pcm_rebuilt = bytearray()
            # for enc_block in speech_chunks:
            #     raw_chunk = base64.b64decode(enc_block)   # 解出单块的 1024 字节（最后一块可能 <1024）
            #     pcm_rebuilt.extend(raw_chunk)
            # speech_str = base64.encode(pcm_rebuilt).decode('utf-8')
            logger.debug(self.speech_cache[uid])
            if len(speech_chunks) < 2 :
                logger.error(f'speech chunks size < 2, uid:{uid}, chunk: {len(speech_chunks)}')
                speech_chunks[0] = [{'totalLength': 0, 'total': 0, 'speech': 'special'}]

            first_chunk = next(iter(speech_chunks.values()))
            chunk_size = first_chunk['total']

            parse_chunks = []
            speech_str = ''

            for idx in range(1, chunk_size) :
                if idx not in speech_chunks :
                    logger.error(f'speech idx:{idx} do not receive.')
                    return None

                chunk = speech_chunks[idx]
                if len(chunk['speech']) != chunk['length'] :
                    logger.error(f"chunk idx:{idx}, src_size:{chunk['length']} != receive_size:{len(chunk['speech'])}")
                    return None

                parse_chunks.append(chunk['speech'])

                # if 'speech' in chunk['speech'] :
                #     chunk = json.loads(chunk['speech'])

                speech_str += chunk['speech']

            speech_str = ''.join(parse_chunks)
            if len(speech_str) != first_chunk['totalLength'] :
                logger.error(f"join speech size:{len(speech_str)} != src_size:{speech_chunks[0]['totalLength']}")
                return None


            req = {
                'format': 'mp3',
                'text' : None,
                'speech' : speech_str
            }
            t2 =  time.perf_counter()
            logger.debug(f'decode speech, len={len(speech_chunks)}, use time={t2-t1}')
            self.speech_cache = {}

        return req

    def _parse_speech2(self, req) :
        uid = req['uid']
        speech = req['speech']
        state = req['state']

        if uid not in self.speech_cache :
            self.speech_cache[uid] = {
                req['idx'] : req
            }
        else :
            self.speech_cache[uid][req['idx']] = req

        req = None
        if state == 'finish' :
            t1 = time.perf_counter()
            speech_chunks = self.speech_cache[uid]
            # pcm_rebuilt = bytearray()
            # for enc_block in speech_chunks:
            #     raw_chunk = base64.b64decode(enc_block)   # 解出单块的 1024 字节（最后一块可能 <1024）
            #     pcm_rebuilt.extend(raw_chunk)
            # speech_str = base64.encode(pcm_rebuilt).decode('utf-8')

            # self.speech_cache["speech"] = len(self.speech_cache["speech"])
            # 创建日志副本，不修改原始数据
            speech_cache_log = {}
            for uid_key in self.speech_cache:
                speech_cache_log[uid_key] = {}
                for idx_key in self.speech_cache[uid_key]:

                    chunk_copy = self.speech_cache[uid_key][idx_key].copy()
                    if 'speech' in chunk_copy and isinstance(chunk_copy['speech'], str):
                        chunk_copy['speech'] = len(chunk_copy['speech'])
                    speech_cache_log[uid_key][idx_key] = chunk_copy

            logger.debug(f'speech cache: {speech_cache_log}')
            first_chunk = next(iter(speech_chunks.values()))
            chunk_size = first_chunk['total']

            parse_chunks = []
            speech_str = ''

            for idx in range(0, chunk_size) :
                if idx not in speech_chunks :
                    logger.error(f'speech idx:{idx} do not receive.')
                    return None

                chunk = speech_chunks[idx]
                if len(chunk['speech']) != chunk['length'] :
                    logger.error(f"chunk idx:{idx}, src_size:{chunk['length']} != receive_size:{len(chunk['speech'])}")
                    return None

                parse_chunks.append(chunk['speech'])

                if 'speech' in chunk['speech'] :
                    chunk = json.loads(chunk['speech'])

                speech_str += chunk['speech']

            speech_str = ''.join(parse_chunks)
            if len(speech_str) != first_chunk['totalLength'] :
                logger.error(f"join speech size:{len(speech_str)} != src_size:{speech_chunks[0]['totalLength']}")
                return None

            # save_base64_to_wav(speech_str, f'speech_{uid}.wav')

            req = {
                'format' : 'mp3',
                'uid': uid,
                'text' : None,
                'speech' : speech_str
            }

            if 'format' in first_chunk :
                req['format'] = first_chunk['format']

            t2 =  time.perf_counter()
            logger.debug(f'decode speech, len={len(speech_chunks)}, use time={t2-t1}')
            self.speech_cache = {}

        return req

    def _speech_request(self, config_req):

        req = self._parse_speech(config_req)
        if req is not None :
            self.robot.speech_stream_.append(req)

        return STATE_SUCCESS, 'speech request success', None    

    def _speech_request2(self, config_req):
        req = self._parse_speech2(config_req)
        if req is not None :
            self.robot.speech_stream_.append(req)

        return STATE_SUCCESS, 'speech request success', None

    def _add_exihibition(self, config_req):
        self.robot.config_manager_.add_exhibition(config_req)
        self.robot.config_manager_.save_exhibition()
        self.robot.interrupt()

        self.robot.wss.close()

        return STATE_SUCCESS, 'add exihibition success', None

    def _query_exihibition(self, config_req):
        data = self.robot.config_manager_.exhibition_config_
        return STATE_SUCCESS, 'query exihibition success', data

    def _delete_exihibition(self, config_req):
        self.robot.config_manager_.del_exhibition(config_req)
        self.robot.config_manager_.save_exhibition()
        self.robot.interrupt()

        self.robot.wss.close()

        return STATE_SUCCESS, 'delete exihibition success', None

    def _get_knowledge_temp(self, config_req):
        data = self.robot.config_manager_.get_knowledge_temp()

        return STATE_SUCCESS, 'get knowledge temp success', data

    def _upload_knowledge(self, config_req):
        self.robot.config_manager_.add_knowledge(config_req)

        self.robot.wss.close()

        return STATE_SUCCESS, 'upload knowledge success', None

    def _get_knowledge(self, config_req):
        data = self.robot.config_manager_.knowledge_config_

        return STATE_SUCCESS, 'get knowledge success', data

    def _delete_knowledge(self, config_req):
        self.robot.config_manager_.del_knowledge(config_req)

        self.robot.wss.close()

        return STATE_SUCCESS, 'delete knowledge success', None

    def _update_llm_api(self, config_req):
        self.robot.config_manager_.basic_config_['llm_api'].update(config_req)

        self.robot.config_manager_.save_basic()

        self.robot.wss.close()

        return STATE_SUCCESS, 'update llm api success', None

    def _get_llm_api(self, config_req):
        data = self.robot.config_manager_.basic_config_['llm_api']
        return STATE_SUCCESS, 'get llm api success', data

    def _auto_nav_switch_get(self, config_req):
        data = {
            'enable' : self.robot.config_manager_.basic_config_['auto_nav'],
            'auto_nav_interval' : self.robot.config_manager_.basic_config_['auto_nav_interval'],
        }

        return STATE_SUCCESS, 'auto nav switch get success', data

    def _auto_nav_switch_update(self, config_req):
        self.robot.config_manager_.basic_config_['auto_nav'] = config_req['enable']

        if 'auto_nav_interval' in config_req :
            self.robot.config_manager_.basic_config_['auto_nav_interval'] = config_req['auto_nav_interval']

        self.robot.config_manager_.save_basic()

        self.robot.interrupt()

        return STATE_SUCCESS, 'auto nav switch update success', None

    def _role_set(self, config_req):
        self.robot.config_manager_.basic_config_['name'] = config_req['name']

        self.robot.config_manager_.save_basic()

        self.robot.wss.close()

        return STATE_SUCCESS, 'role set success', None

    def _role_get(self, config_req):
        data = {
            'name' : self.robot.config_manager_.basic_config_['name']
        }

        return STATE_SUCCESS, 'role get success', data

    def _gesture_set(self, data) :
        self.robot.config_manager_.basic_config_['gesture_switch'] = data['enable']

        self.robot.config_manager_.save_basic()

        return STATE_SUCCESS, 'gesture set success', None

    def _gesture_get(self) :
        data = {
            "enable" : self.robot.config_manager_.basic_config_['gesture_switch']
        }

        return STATE_SUCCESS, 'gesture get success', data

    def  _on_data_available(self, dr: DataReader):
        try:
            datas = dr.take()
            # datas[0].parameter["speech"] = len(datas[0].parameter["speech"])

            # 检查是否有有效数据
            if not datas or len(datas) == 0:
                return

            # 检查第一个样本是否有效
            if not isinstance(datas[0], Request_):
                logger.warning(f'Invalid sample received: {type(datas[0])}')
                return

            try:
                data_log = json.loads(datas[0].parameter)
                # 检查是否包含 speech 字段
                if 'speech' in data_log:
                    data_log["speech"] = len(data_log["speech"])
                logger.debug(f'ConfigThread on_data_available, data Request: {datas[0].header}, {data_log}')
            except Exception as e:
                pass

            for data in datas:
                data = datas[0]
                if not isinstance(data, Request_) :
                    logger.error(f'ConfigThread on_data_available, data type error: {type(data)}')
                    continue

                config_req, api_id, msg_id = data.parameter, data.header.identity.api_id, data.header.identity.id

                if config_req != '' and '{' in config_req :
                        config_req = json.loads(config_req)

                if api_id in self.callbacks_ :                
                    status, desc, data = self.callbacks_[api_id](config_req)
                else :
                    desc = (f'api_id : {api_id} not surport! data: {config_req}')
                    status = STATE_FAIL
                    data = None

                app_msg = {
                    'status' : status,
                    'desc' : desc,
                }

                if data is not None :
                    app_msg['data'] = data

                if api_id == CONFIG_API_ID_AUDIO_REQUEST :
                    app_msg = 'ack'

                pub_app_config(msg_id, api_id, app_msg)
                config_req_log = config_req.copy() if isinstance(config_req, dict) else config_req

                # 只有当包含 speech 字段时才替换为长度
                if isinstance(config_req_log, dict) and 'speech' in config_req_log:
                    config_req_log["speech"] = len(config_req_log["speech"])

                logger.debug(f'req: {config_req_log}, res:')
        except Exception as e:
            logger.error(f'ConfigThread on_data_available error: {traceback.format_exc()}')

        return

    def _gettunelist(self, data):

        tune_list = self.robot.config_manager_.tts_config_

        return STATE_SUCCESS, 'tunelist get success', tune_list


    def _saveselecttune(self, config_req):

        self.robot.config_manager_.basic_config_['speaker_id'] = config_req['speaker_id']

        self.robot.config_manager_.save_basic()
        self.robot.config_manager_.update_tts_config_ = True

        return STATE_SUCCESS, 'save selected tune success', None


    def _gettuneresult(self, req_data):

        data = {
            "speaker_id" : self.robot.config_manager_.basic_config_['speaker_id']
        }

        return STATE_SUCCESS, 'get tune result success', data


    def run(self) :
        logger.info ('start app reader thread')
        while self.is_running :
            try:
                time.sleep(0.1)
                # self._pub_gpt_state()

                config_req, api_id, msg_id = sub_app_config()
                if config_req is None :
                    continue

                if config_req != '' and '{' in config_req :
                    config_req = json.loads(config_req)

                if api_id in self.callbacks_ :                
                    status, desc, data = self.callbacks_[api_id](config_req)
                else :
                    desc = (f'api_id : {api_id} not surport! data: {config_req}')
                    status = STATE_FAIL
                    data = None

                app_msg = {
                    'status' : status,
                    'desc' : desc,
                }

                if data is not None :
                    app_msg['data'] = data

                if api_id == CONFIG_API_ID_AUDIO_REQUEST :
                    app_msg = 'ack'

                pub_app_config(msg_id, api_id, app_msg)
                config_req["speech"] = len(config_req["speech"])
                logger.debug(f'req: {config_req}, res:')
            except Exception as e :
                logger.error(f'ConfigThread error: {traceback.format_exc()}')

    send_data['text'] = text
    send_data['action'] = action
    send_data['lang'] = anser_lang

    if msg_state == CODE_STATE :
        send_data['state'] = 'function_call'
    elif msg_state == FINISH_STATE :
        send_data['state'] = 'finish'
    else :
        send_data['state'] = 'text_generate'

    response['data'] = send_data

    tmp = json.dumps(response, ensure_ascii=False)
    return  tmp

def on_zmq_response(self, response):
    logger.debug(f"on_zmq_response: {response}")
    self.buffer += response

    buffer = self.buffer
    msg_queue = self.msg_queue
    msg_state = self.msg_state
    ret_text, ret_code, self.buffer, self.msg_queue, self.msg_state = parse_text(buffer, msg_queue, msg_state)

    tmp = self.zmq2answer(CMD_ACTION, self.zmq_uid, ret_text, ret_code, msg_state, self.lang_)

    self.on_message(tmp)
    return

def on_zmq_finish(self, data:Any) :
    logger.debug(f"on_zmq_finish: {data}")
    tmp = self.zmq2answer(CMD_ACTION, self.zmq_uid, "", "", FINISH_STATE, self.lang_)

    self.on_message(tmp)

    return

def zmq_intterrupt(self, question) :
    self.zmq_uid = question['uid']

    tmp = self.zmq2answer(CMD_interrupt_SPEAK, self.zmq_uid, "", "", TEXT_STATE, self.lang_)

    self.on_message(tmp)

    self.clear_buffer()

    return

def send_msg(self, question):
    if G_ROBOT_TYPE.name.endswith('_stream'):
        self.openai_sdk_queue_.put(question)
        return

    if self.state_thread_.clound_server is True :
        self.wss.send(question)
    elif self.state_thread_.local_server is True :
        data = question['data']
        self.zmq_intterrupt(data)

        message_dict = {
            "text": data['question'],
            "image": data['vision']
        }
        zmq_data = {
            "api" : "/api/generate",
            "data" : json.dumps(message_dict,ensure_ascii=False)
        }
        self.llm_zmq_client_thread_.send_question(zmq_data)
    else :
        logger.error(f"llm server is not ready")

    return

def sub_power_event(self) :
    event = sub_key_slam()
    if event is None :
        return None

    # logger.debug(event)
    if event['type'] != 'task_result' :
        return None

    if len(self.config_manager_.exhibition_config_) < 1 :
        return None

    # event = event[0]
    data = event['data']

    level = EVENT_LEVEL_NORMAL
    if data['is_arrived'] :
        if self.config_manager_.basic_config_['auto_nav'] is False or self.interrupt_auto_nav_:
            desc = '目标已达到，请详细介绍该导航点。如果所有目标已经去过，就总结行程或者询问客户意图。'
        else :
            desc = '目标已达到，请选择下一个目标点。'

        nav_type = EVENT_NAVIGATION
    else :
        desc = event['info']
        if self.lang_ == LANG_CN :
            desc += f"发生导航错误，请查看日志。"
        level = EVENT_LEVEL_ERROR
        nav_type = EVENT_NAV_ERROR

    desc = f"target_id={data['targetNodeName']}, {desc}"

    msg = {
        'type' : nav_type,
        'level' : level,
        'desc' : desc
    }

    self.add_event(msg)

    self.is_slam_finished_ = True

    return msg

