def register_function(name: str, fn: Callable, description: str = "") -> Callable:
    """
    Register a function into available_functions and auto-fill __doc__.
    If fn already has __doc__, keep it; otherwise use description.
    """
    if callable(fn):
        if description and not (fn.__doc__ or "").strip():
            fn.__doc__ = description
        available_functions[name] = fn
    return fn


def tool(name: str, description: str = ""):
    """
    Decorator for tool registration.
    Example:
        @tool("google_search", "Search web by query_word.")
        def search_engine(query): ...
    """
    def decorator(fn: Callable) -> Callable:
        return register_function(name, fn, description)

    return decorator


