                                    "check_hostname": True
                                },
                            )
            ws.close()
            return True
        except websocket._exceptions.WebSocketBadStatusException as e:
            if e.status_code in (401, 403):
                # ✅ 鉴权失败 ≠ 网络失败
                return True
        except Exception as e:
            pass

        return False

