        logger.debug ('start pub state thread')



        while self.is_running :
            try:
                self.clound_server = self._check_clound_server()
                self.local_server = self._check_local_server()
                self.cloud_tts = self._check_cloud_tts()
                self.speak_state = self._check_speak_state()


                self.gpt_state  = True
                if self.clound_server is False and self.local_server is False :
