def scale_volume(msg, target_peak=0.9):
    pcm = np.frombuffer(msg['data'], dtype=np.int16)

    max_val = np.max(np.abs(pcm))
    if max_val == 0:
        return msg

    # scale = (32767 * target_peak) / max_val
    scale = 1.5
    pcm_scaled = pcm.astype(np.float32) * scale
    pcm_scaled = np.clip(pcm_scaled, -32768, 32767)

    msg['data'] = pcm_scaled.astype(np.int16).tobytes()
    return msg

class PlayerThread(threading.Thread) :
    def __init__(self, in_queue) :
        super().__init__()
        self.in_queue_ = in_queue
        self.is_running_ = True
        self.daemon = True
        self.player_ = AudioPlayer(RATE)

    def run(self) :
        logger.info ('player thread start')

        while self.is_running_ :
            try:
                msg = self.in_queue_.get()
                if msg is None :
                    continue

                msg = scale_volume(msg)
                self.player_.play(msg)
            except Exception as e :
                logger.error(f'player thread error: {e}')

